def _(zh, en):
    return zh if LANG == "zh" else en

def logwrite(process):
    if os.path.isfile("pizza.log"):
        if os.path.getsize("pizza.log") != 0:
            with open("pizza.log", "a", encoding='utf-8') as log:
                log.write(f"\n------------------------------ {time.strftime('%Y-%m-%d %H:%M:%S')} ------------------------------\n\n")
        else:
            with open("pizza.log", "a", encoding='utf-8') as log:
                log.write(f"------------------------------ {time.strftime('%Y-%m-%d %H:%M:%S')} ------------------------------\n\n")
    else:
        with open("pizza.log", "a", encoding='utf-8') as log:
            log.write(f"------------------------------ {time.strftime('%Y-%m-%d %H:%M:%S')} ------------------------------\n\n")

    def write(text):
        with open("pizza.log", "a", encoding='utf-8') as log:
            for line in text:
                log.write(line)
                log.flush()

    t = threading.Thread(target=write, args=(process.stdout,))
    t.start()

def buildrun(data, build, olnydep=False):
    if "main" not in data:
        print(_("\033[91m[错误] \033[4mpizza.json\033[24m 缺少 \033[4mmain\033[24m 字段\033[0m", "\033[91m[Error] \033[4mpizza.json\033[24m missing \033[4mmain\033[24m field\033[0m"))
        return
    if data.get("build") is None:
        data["build"] = {"console":True,"skip":False}
    if data.get("build").get("console") is None:
        data["build"]["console"] = True
    if data.get("build").get("skip") is None:
        data["build"]["skip"] = False
    if data.get("deps") is None:
        data["deps"] = []

    try:
        func = data["main"].split(":")[1]
    except:
        print(_("\033[91m[错误] \033[4mpizza.json\033[24m 的 \033[4mmain\033[24m 字段没有指定入口点\033[0m", "\033[91m[Error] \033[4mpizza.json\033[24m main field missing entry point\033[0m"))
        return

    data["main"] = data["main"].split(":")[0]
    tmpfile      = os.path.join(os.path.dirname(data['main']), f".pizza_{os.path.basename(data['main'])}")

    p, n = 0, 1
    all  = len(data["deps"])

    for dep in data["deps"]:
        try:
            long = cnlen(max(data["deps"], key=len)) - cnlen(dep)
            process = subprocess.Popen(
                ['pip', 'install', dep],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True
            )
            logwrite(process)
            while True:
                try:
                    bar   = ["|", "/", "-", "\\"]
                    order = [0, 1, 2, 3]
                    if p >= len(order):
                        p = 0
                    print(_("[第", "[dependencies: ") + "0" * (len(f"{all}") - len(f"{n}")) + f"{n}/{all}" + _("个依赖", "") + f"] {dep}{' ' * long} | \033[36m{bar[order[p]]}\033[0m", end='\r', flush=True)
                    result = process.poll()
                    if result is not None:
                        if result != 0:
                            print(_("[第", "[dependencies: ") + "0" * (len(f"{all}") - len(f"{n}")) + f"{n}/{all}" +
                                  _("个依赖", "") + f"] {dep}{' ' * long} | \033[91m" + _("ERROR", "ERROR") + "\033[0m", end='')
                            if not data.get("build").get("skip"):
                                print("\r", end='')
                                raise
                            else:
                                print()
                                break

                        else:
                            print("\r", end='')
                            print("\033[K", end='')
                            print(_("[第", "[dependencies: ") + "0" * (len(f"{all}") - len(f"{n}")) + f"{n}/{all}"+
                                  _("个依赖", "") + f"] {dep}{' ' * long} | \033[92m" + _("OK", "OK") + "\033[0m")
                            break

                    p += 1
                    time.sleep(0.5)
                except KeyboardInterrupt:
                    print()
                    exit()

            n += 1

        except Exception as e:
            print(_("[第", "[dependencies: ") + "0" * (len(f"{all}") - len(f"{n}")) + f"{n}/{all}" +
                  _("个依赖", "") + f"] {dep}{' ' * long} | \033[91m" + _("ERROR", "ERROR") + "\033[0m", end='')
            if not data.get("build").get("skip"):
                return
            else:
                n += 1
                continue

    if not olnydep:
        with open(tmpfile, "w", encoding="utf-8") as file:
            file.write(open(data["main"], "r", encoding="utf-8").read() + f"\nif __name__ == '__main__':\n    {func}()")

        if not build:
            subprocess.run(["python" if os.name == "nt" else "python3", tmpfile] + runargs)
            os.remove(tmpfile)

        else:
            if data["main"][-3:] == ".py":
                exe    = os.path.basename(data["main"][:-3] + ".exe")
                spec   = os.path.basename(data["main"][:-3] + ".spec")
                output = os.path.basename(data["main"][:-3])
            else:
                exe    = os.path.basename(data["main"] + ".exe")
                spec   = os.path.basename(data["main"] + ".spec")
                output = os.path.basename(data["main"])

            if build:
                if len(sys.argv) <= 2:
                    lines    = tree(".")
                    in033    = False
                    newlines = []

                    for line in lines:
                        newline  = ""
                        for b in line:
                            if b != "\033" and not in033:
                                newline += b
                            elif b == "\033":
                                in033 = True
                            elif b == "m":
                                in033 = False

                        newlines.append(newline)

                    long = max(cnlen(line) for line in newlines)

                    if data["deps"]:
                        print()

                    print( "╭─ " + _("项目结构", "Project Structure") + " " + "─" * (_(long-9, long-18)) + "╮")
                    print(f"│ \033[97m{os.path.basename(os.getcwd())}/\033[0m" +
                          (" " * (long - cnlen(os.path.basename(os.getcwd()))) + "│"))

                    pos = 0
                    for line in lines:
                        padding = long - cnlen(newlines[pos])
                        print(f"│ {line}{' ' * padding} │")
                        pos += 1

                    print("╰" + "─" * (long+2) + "╯")
                    print()

                print("\r\033[K", end='')
                print(_("╭─ Pizza ──────" + "─" * cnlen(f"output/{exe}") + "╮",
                        "╭─ Pizza ──────────────" + "─" * cnlen(f"output/{exe}") + "╮"))
                print(_("│              " + " " * cnlen(f"output/{exe}") + "│",
                        "│                      " + " " * cnlen(f"output/{exe}") + "│"))
                print(_("╰──────────────" + "─" * cnlen(f"output/{exe}") + "╯",
                        "╰──────────────────────" + "─" * cnlen(f"output/{exe}") + "╯"))
                try:
                    with open("pizza.ico", "wb") as f:
                        f.write(base64.b64decode(DATA))

                    if data.get("build").get("icon"):
                        process = subprocess.Popen(
                            f'pyinstaller {tmpfile} --onefile --name {output}' +
                            f' --icon={data.get("build").get("icon")}' +
                            (" --noconsole" if not data.get("build").get("console") else ""),
                            shell=True,
                            stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT,
                            text=True
                        )
                    else:
                        process = subprocess.Popen(
                            f'pyinstaller {tmpfile} --onefile --name {output}' +
                            f' --icon=pizza.ico' +
                            (" --noconsole" if not data.get("build").get("console") else ""),
                            shell=True,
                            stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT,
                            text=True
                        )
                    logwrite(process)
                    n = 0
                    print("\033[F", end='')
                    print("\033[F", end='')
                    while True:
                        try:
                            bar   = ["|", "/", "-", "\\"]
                            order = [0, 1, 2, 3]
                            if n >= len(order):
                                n = 0
                            print("│ \033[93m" + _("编译中", "Building") + "\033[0m \033[36m" + bar[order[n]] + "\033[0m", end='\r', flush=True)
                            result = process.poll()
                            if result is not None:
                                if result != 0:
                                    print( "│ \033[91m" + _("编译失败", "Build failed") + "\033[0m")
                                    print(_("╰──────────────" + "─" * cnlen(f"output/{exe}") + "╯",
                                            "╰──────────────────────" + "─" * cnlen(f"output/{exe}") + "╯"))
                                    return
                                else:
                                    print(  "│ \033[92m" + _("编译成功", "Build successful") + f"\033[0m \033[93m->\033[0m \033[4moutput/{exe}\033[0m")
                                    print(_("╰──────────────" + "─" * cnlen(f"output/{exe}") + "╯",
                                            "╰──────────────────────" + "─" * cnlen(f"output/{exe}") + "╯"))
                                    return

                            n += 1
                            time.sleep(0.5)

                        except KeyboardInterrupt:
                            print()
                            print()
                            exit()

                except Exception as e:
                    print(_("\033[91m[错误] 编译失败: {}\033[0m".format(e), "\033[91m[Error] Build failed: {}\033[0m".format(e)))
                finally:
                    try:
                        try:
                            os.makedirs("output")
                        except:
                            pass
                        shutil.move(os.path.join("dist", exe), os.path.join("output", exe))
                    except:
                        pass
                    try:
                        shutil.rmtree("dist")
                    except:
                        pass
                    try:
                        shutil.rmtree("build")
                    except:
                        pass
                    try:
                        os.remove("pizza.ico")
                    except:
                        pass
                    try:
                        os.remove(spec)
                    except:
                        pass
                    try:
                        os.remove(tmpfile)
                    except:
                        pass

def tree(path, prefix="", lines=None):
    if lines is None:
        lines = []

    EXCLUDE      = ("output", "pizza.log", "dist", "build", "tmp", "temp", "__pycache__", ".git", ".vscode")
    STARTEXCLUDE = (".", ".pizza_", "tmp_", ".tmp_", ".temp_", "temp_")
    ENDEXCLUDE   = (".tmp", ".temp", ".log", ".egg-info")

    if not os.path.exists(path):
        return lines

    try:
        items = os.listdir(path)
    except PermissionError:
        return [f"{prefix}└─ " + _("权限不足", "Permission denied")]

    items.sort()

    for i, item in enumerate(items):
        if item not in EXCLUDE and not (item.startswith(STARTEXCLUDE) or item.endswith(ENDEXCLUDE)):
            is_last_item = (i == len(items) - 1)
            full_path = os.path.join(path, item)
            connector = "└─ " if is_last_item else "├─ "

            if os.path.isdir(full_path):
                line = f"{prefix}{connector}\033[97m{item}/\033[0m"
                lines.append(line)
                new_prefix = prefix + ("    " if is_last_item else "│   ")
                tree(full_path, new_prefix, lines)
            else:
                size = os.path.getsize(full_path)
                if size < 1024:
                    size_str = f"{size} B"
                elif size < 1024 * 1024:
                    size_str = f"{size/1024:.1f} KB"
                else:
                    size_str = f"{size/(1024*1024):.1f} MB"

                line = f"{prefix}{connector}{item} \033[90m[{size_str}]\033[0m"
                lines.append(line)

    return lines

def cnlen(text):
    length = 0
    for char in str(text):
        code = ord(char)
        if (0x4E00  <= code <= 0x9FFF  or
            0x3400  <= code <= 0x4DBF  or
            0x20000 <= code <= 0x2A6DF or
            0x2A700 <= code <= 0x2B73F or
            0x2B740 <= code <= 0x2B81F or
            0x2B820 <= code <= 0x2CEAF or
            0x2CEB0 <= code <= 0x2EBEF or
            0x30000 <= code <= 0x3134F or
            0xF900  <= code <= 0xFAFF  or
            0x2F800 <= code <= 0x2FA1F or
            0xFF00  <= code <= 0xFFEF  or
            char in '，。！？；：「」【】（）《》'):
            length += 2
        else:
            length += 1
    return length

