def main(args=None):
    if os.name != "nt":
        print(_(f"\033[38;5;220m[警告] Pizza 对 {platform.system()} 系统实验性支持\033[0m",
                f"\033[38;5;220m[Warning] Pizza has experimental support for {platform.system()}\033[0m"))
    try:
        if args is None:
            args = sys.argv

        global runargs

        runargs = []
        pos  = None
        i    = 0
        for arg in sys.argv:
            if arg == "--":
                pos = i
                break
            i += 1

        if pos is not None:
            try:
                runargs = [a for a in sys.argv[pos+1:]]
            except:
                runargs = []

            args = [a for a in sys.argv[:pos+1]]

        if len(args) <= 1:
            help()
            return

        try:
            if args[1] not in ["build", "run", "clean", "new", "info", "add", "remove", "set", "publish", "freeze", "install"] or args[1] == "help":
                ret = project.scripts(args[1])
                if ret == 127:
                    if args[1] != "help":
                        print(_("\033[91m[错误] 没有这个参数\033[0m",
                                "\033[91m[Error] Unknown parameter\033[0m"))

                    help()

                return

            if args[1] == "publish":
                project.publish()
                return

            if args[1] == "freeze":
                if len(args) >= 3:
                    project.freeze(args[2])
                else:
                    print(_("\033[91m[错误] \033[4mfreeze\033[24m 参数需要文件名称\033[0m",
                            "\033[91m[Error] \033[4mfreeze\033[24m requires file name\033[0m"))

            if args[1] == "new":
                if len(args) >= 3:
                    project.new(args[2])
                else:
                    print(_("\033[91m[错误] \033[4mnew\033[24m 参数需要项目名称\033[0m",
                            "\033[91m[Error] \033[4mnew\033[24m requires project name\033[0m"))

                return

            if args[1] == "info":
                project.info()
                return

            if args[1] in ["build", "run"] and len(args) >= 3 and args[2] != "--":
                icon = None
                pos  = None
                i    = 0
                for arg in args:
                    if arg == "-i":
                        pos = i
                        break
                    i += 1

                if pos is not None:
                    try:
                        icon = args[pos + 1]
                    except IndexError:
                        print(_("\033[91m[错误] \033[4m-i\033[24m 参数需要一个图标文件\033[0m",
                                "\033[91m[Error] \033[4m-i\033[24m requires an icon file\033[0m"))
                        return

                try:
                    func    = args[2].split(":")[1]
                    args[2] = args[2].split(":")[0]

                except:
                    buildrun({
                        "main": f"{args[2]}:main",
                        "build": {
                            "icon": icon if icon else None,
                            "console": False if "-g" in args else True,
                            "skip": False if "-s" in args else True
                        }}, build = True if args[1] == "build" else False)
                    return

                buildrun({
                    "main": f"{args[2]}:{func}",
                    "build": {
                        "icon": icon if icon else None,
                        "console": False if "-g" in args else True,
                        "skip": True if "-s" in args else False
                    }}, build = True if args[1] == "build" else False)

                return

            if args[1] == "install":
                project.install()
                return

            if args[1] == "run":
                project.run(build=False)
                return

            if args[1] == "build":
                project.run(build=True)
                return

            if args[1] == "add":
                if len(args) >= 3:
                    project.deps.add(','.join(args[2:]))
                else:
                    print(_("\033[91m[错误] \033[4madd\033[24m 参数需要依赖名称\033[0m",
                            "\033[91m[Error] \033[4madd\033[24m requires some dependencies\033[0m"))

                return

            if args[1] == "remove":
                if len(args) >= 3:
                    project.deps.remove(','.join(args[2:]))
                else:
                    print(_("\033[91m[错误] \033[4mremove\033[24m 参数需要依赖名称\033[0m",
                            "\033[91m[Error] \033[4mremove\033[24m requires some dependencies\033[0m"))

                return

            if args[1] == "set":
                if len(args) >= 3:
                    if args[2] == "null":
                        project.deps.set("")
                    else:
                        project.deps.set(','.join(args[2:]))
                else:
                    print(_("\033[91m[错误] \033[4mset\033[24m 参数需要依赖名称\033[0m",
                            "\033[91m[Error] \033[4mset\033[24m requires some dependencies\033[0m"))

                return

            if args[1] == "clean":
                try:
                    shutil.rmtree("output")
                except:
                    pass
                try:
                    shutil.rmtree("dist")
                except:
                    pass
                try:
                    shutil.rmtree("build")
                except:
                    pass
                try:
                    os.remove("pizza.ico")
                except:
                    pass
                try:
                    os.remove("pizza.log")
                except:
                    pass
                for file in glob.glob("**/.pizza_*", recursive=True):
                    try:
                        os.remove(file)
                    except:
                        continue
                for file in glob.glob("*.spec"):
                    try:
                        os.remove(file)
                    except:
                        continue
                for file in glob.glob("**/*.egg-info/", recursive=True):
                    try:
                        shutil.rmtree(file)
                    except:
                        pass

                return

        except Exception as e:
            print(_("\033[91m[错误] {}\033[0m".format(e), "\033[91m[Error] {}\033[0m".format(e)))

    except KeyboardInterrupt:
        exit()

    except Exception as e:
        print(_("\033[91m[错误] {}\033[0m".format(e), "\033[91m[Error] {}\033[0m".format(e)))

if __name__ == "__main__":
    try:
        main(sys.argv)
    except KeyboardInterrupt:
        exit()
    except Exception as e:
        print(_("\033[91m[错误] {}\033[0m".format(e), "\033[91m[Error] {}\033[0m".format(e)))

    finally:
        for file in glob.glob("**/.pizza_*", recursive=True):
            try:
                os.remove(file)
            except:
                pass

        for file in glob.glob("**/*.egg-info/", recursive=True):
            try:
                shutil.rmtree(file)
            except:
                pass
